suite=ET.Element('testsuite',name='CommandRoot.Compile',tests=str(len(cases))); failed=0
with tempfile.TemporaryDirectory(dir=out.resolve()) as d:
    p=pathlib.Path(d); (p/'Test.csproj').write_text(f'<Project Sdk="Microsoft.NET.Sdk"><PropertyGroup><TargetFramework>net11.0</TargetFramework><LangVersion>15</LangVersion><Nullable>enable</Nullable><TreatWarningsAsErrors>true</TreatWarningsAsErrors></PropertyGroup><ItemGroup><ProjectReference Include="{root / "spikes/CommandRoot/CommandRoot.csproj"}" /><ProjectReference Include="{root / "spikes/CommandRoot.Generator/Generator.csproj"}" OutputItemType="Analyzer" ReferenceOutputAssembly="false" /></ItemGroup></Project>')
    for name,source,expected in cases:
        (p/'Test.cs').write_text('using CommandRoot; namespace CompilerCase { '+source+' }')
        result=subprocess.run([dotnet,'build',str(p/'Test.csproj'),'--nologo','-v:q','-t:Rebuild'],capture_output=True,text=True)
        log=result.stdout+result.stderr; (out/(name+'.log')).write_text(log); ok=(result.returncode==0 if expected is None else result.returncode!=0 and expected in log and 'CS8785' not in log) and 'MSB3202' not in log
        node=ET.SubElement(suite,'testcase',name=name)
        if not ok: failed+=1; ET.SubElement(node,'failure',message='Expected '+(expected or 'success')).text=log
        print(name, 'PASS' if ok else 'FAIL')
suite.set('failures',str(failed)); ET.ElementTree(suite).write(out/'compile.xml',encoding='utf-8',xml_declaration=True)
raise SystemExit(bool(failed))
